#!/bin/sh
# Generated by YDK go-http-service from ydk:test:system/round-trip.e2e.
# Functional cases run first; kafka-down and restart-resume change shared cluster state and run last.
# kubectl is used only for orchestration and assertions; app traffic stays HTTP via the Ingress.
set -eu
. "$(dirname "$0")/lib.sh"

RUN="$$-$(date +%s)"
: "${NAMESPACE:=clopy-paste}"
: "${KAFKA_CLUSTER:=kafka}"
: "${CURL_IMAGE:=curlimages/curl:8.11.1}"
BROKER_POD="$KAFKA_CLUSTER-dual-role-0"

# send <host> <user> <text>: POST a message; fails unless 202.
send() {
  [ "$(http_status "$1" POST /api/messages "{\"user\":\"$2\",\"text\":\"$3\"}")" = 202 ] || fail "POST $2 on $1 not 202"
}

# messages <host> <user>: prints the JSON array for the user.
messages() {
  http_get "$1" "/api/messages?user=$2"
}

# nap: sub-second pause; sleep 0.25 is not POSIX, so fall back to 1 s.
nap() {
  sleep 0.25 2>/dev/null || sleep 1
}

# wait_text <host> <user> <fixed-string...>: poll every 250 ms up to 10 s until the body contains any of the strings.
wait_text() {
  wt_host=$1
  wt_user=$2
  shift 2
  wt_i=0
  while [ "$wt_i" -lt 40 ]; do
    wt_body=$(messages "$wt_host" "$wt_user") || wt_body=
    for wt_s in "$@"; do
      case "$wt_body" in *"$wt_s"*) return 0 ;; esac
    done
    wt_i=$((wt_i + 1))
    nap
  done
  fail "'$1' not seen for $wt_user on $wt_host within 10 s (last body: $wt_body)"
}

# post_check <host> <json> <status> <error message>: POST and assert status and exact error body.
post_check() {
  pc_out=$(curl -sS -w '\n%{http_code}' -H "Host: $1" -H 'Content-Type: application/json' -d "$2" "$BASE_URL/api/messages")
  pc_code=$(printf '%s' "$pc_out" | tail -n 1)
  pc_body=$(printf '%s' "$pc_out" | sed '$d')
  [ "$pc_code" = "$3" ] || fail "expected status $3, got $pc_code ($pc_body)"
  [ "$pc_body" = "{\"error\":\"$4\"}" ] || fail "expected error '$4', got $pc_body"
}

# warm_up <from-host> <to-host> <tag>: resend a probe every 1 s (up to 30 s) until it arrives, proving the
# receiving consumer group has joined (it starts at latest, ADR-017).
warm_up() {
  wu_i=0
  while [ "$wu_i" -lt 30 ]; do
    send "$1" "warm-$3-$RUN" "probe$3"
    sleep 1
    case "$(messages "$2" "warm-$3-$RUN" || true)" in *"probe$3"*) return 0 ;; esac
    wu_i=$((wu_i + 1))
  done
  fail "warm-up $3 did not arrive within 30 s"
}

wait_ready "$HOST_CLOPY_PASTE_A"
wait_ready "$HOST_CLOPY_PASTE_B"
warm_up "$HOST_CLOPY_PASTE_A" "$HOST_CLOPY_PASTE_B" ab
warm_up "$HOST_CLOPY_PASTE_B" "$HOST_CLOPY_PASTE_A" ba

# ydk:test:system/round-trip.e2e case=a-to-b
# Send on A appears on B
# given: Both releases Ready; warm-up done: probe messages A->B and B->A resent every 1 s (up to 30 s) until each arrives, proving both new consumer groups joined (they start at latest, ADR-017)
# when: POST on A as bob with a unique text; poll GET bob on B every 250 ms up to 10 s
# then: B returns the text; GET bob on A returns [] (ydk:req:messaging/sent-not-stored)
case_a_to_b() {
  u="bob-$RUN"
  t="hello$RUN"
  send "$HOST_CLOPY_PASTE_A" "$u" "$t"
  wait_text "$HOST_CLOPY_PASTE_B" "$u" "$t"
  [ "$(messages "$HOST_CLOPY_PASTE_A" "$u")" = "[]" ] || fail "sent message was stored on A"
}

# ydk:test:system/round-trip.e2e case=b-to-a
# Reply direction (B uses PLAINTEXT, A uses SASL_SSL)
# given: Both releases Ready
# when: POST on B as bob; poll A
# then: A returns the text
case_b_to_a() {
  u="bob-ba-$RUN"
  t="reply$RUN"
  send "$HOST_CLOPY_PASTE_B" "$u" "$t"
  wait_text "$HOST_CLOPY_PASTE_A" "$u" "$t"
}

# ydk:test:system/round-trip.e2e case=censoring
# ydk:req:messaging/censor-denylist end to end
# given: Default CENSOR_CHARS
# when: POST on A user 'eve$' text 'a$b!c~'
# then: GET 'eve_' on B returns 'a_b_c_'; GET 'eve$' on B returns the same
case_censoring() {
  send "$HOST_CLOPY_PASTE_A" "eve$RUN"'$' 'a$b!c~'"$RUN"
  wait_text "$HOST_CLOPY_PASTE_B" "eve${RUN}_" "a_b_c_$RUN"
  case "$(messages "$HOST_CLOPY_PASTE_B" "eve$RUN%24")" in *"a_b_c_$RUN"*) ;; *) fail "censored lookup with raw user missed" ;; esac
}

# ydk:test:system/round-trip.e2e case=limits
# ydk:req:messaging/text-length and ydk:req:messaging/user-length
# given: A Ready
# when: POST 1001-code-point text; POST 129-code-point user
# then: 400 with exact messages; nothing appears on B
case_limits() {
  u="lim-$RUN"
  long_text=$(awk 'BEGIN { for (i = 0; i < 1001; i++) printf "a" }')
  long_user=$(awk 'BEGIN { for (i = 0; i < 129; i++) printf "u" }')
  post_check "$HOST_CLOPY_PASTE_A" "{\"user\":\"$u\",\"text\":\"$long_text\"}" 400 'text must be 1..1000 characters'
  post_check "$HOST_CLOPY_PASTE_A" "{\"user\":\"$long_user\",\"text\":\"x\"}" 400 'user must be 1..128 characters'
  # Sentinel: valid message after the rejected ones proves the pipeline is live; rejected ones are never produced, so none may appear.
  send "$HOST_CLOPY_PASTE_A" "$u" "sentinel$RUN"
  wait_text "$HOST_CLOPY_PASTE_B" "$u" "sentinel$RUN"
  case "$(messages "$HOST_CLOPY_PASTE_B" "$u")" in *aaaaaaaaaa*) fail "rejected message reached B" ;; esac
}

# ydk:test:system/round-trip.e2e case=plain-text
# ydk:req:ui/plain-text-rendering at API level
# given: A Ready
# when: POST text '<img src=x onerror=alert(1)>'
# then: B returns it byte-identical; lint stage greps index.html and fails on any innerHTML or insertAdjacentHTML use
case_plain_text() {
  u="xss-$RUN"
  send "$HOST_CLOPY_PASTE_A" "$u" '<img src=x onerror=alert(1)>'
  # The JSON encoder escapes < and > as \u003c and \u003e; accept both forms.
  wait_text "$HOST_CLOPY_PASTE_B" "$u" '<img src=x onerror=alert(1)>' '\u003cimg src=x onerror=alert(1)\u003e'
}

# ydk:test:system/round-trip.e2e case=lru-eviction
# ydk:req:messaging/lru-eviction
# given: B store fresh (pod restarted)
# when: POST on A for u001..u101 one message each; wait for u101 on B
# then: GET u001 on B returns []; GET u002 returns 1 item
case_lru_eviction() {
  # Ids are scoped by the run id. B is not restarted (HTTP only): earlier users are older than the first of
  # the batch, so it is still the first evicted and the second survives. Sends stay serial with a wait each:
  # topics have 3 partitions, so only waiting per message guarantees arrival order equals send order.
  n=1
  while [ "$n" -le 101 ]; do
    id=$(printf 'u%03d-%s' "$n" "$RUN")
    send "$HOST_CLOPY_PASTE_A" "$id" "m$id"
    wait_text "$HOST_CLOPY_PASTE_B" "$id" "m$id"
    n=$((n + 1))
  done
  first="u001-$RUN"
  second="u002-$RUN"
  [ "$(messages "$HOST_CLOPY_PASTE_B" "$first")" = "[]" ] || fail "$first not evicted"
  cnt=$(messages "$HOST_CLOPY_PASTE_B" "$second" | grep -o "m$second" | wc -l | tr -d ' ')
  [ "$cnt" = 1 ] || fail "$second expected exactly 1 item, got $cnt"
}

# kc <args...>: kubectl in the release namespace.
kc() {
  kubectl -n "$NAMESPACE" "$@"
}

# pod_of <release>: prints the release's pod that is not terminating (empty if none).
pod_of() {
  kc get pod -l "app.kubernetes.io/instance=$1" \
    -o go-template='{{range .items}}{{if not .metadata.deletionTimestamp}}{{.metadata.name}}{{"\n"}}{{end}}{{end}}' | head -n 1
}

# restarts <pod>: prints the container restartCount.
restarts() {
  kc get pod "$1" -o jsonpath='{.status.containerStatuses[0].restartCount}'
}

# has_text <host> <user> <fixed-string>: succeeds when the user's messages contain the string.
has_text() {
  case "$(messages "$1" "$2" || true)" in *"$3"*) return 0 ;; esac
  return 1
}

# now_ms: wall clock in milliseconds (GNU date).
now_ms() {
  date +%s%3N
}

# latency_ms <from-host> <to-host> <user> <text>: prints ms from the POST until the text is readable on <to-host>.
latency_ms() {
  lm_start=$(now_ms)
  send "$1" "$3" "$4"
  lm_i=0
  while [ "$lm_i" -lt 40 ]; do
    if has_text "$2" "$3" "$4"; then
      echo $(($(now_ms) - lm_start))
      return 0
    fi
    lm_i=$((lm_i + 1))
    nap
  done
  fail "latency probe $4 not seen on $2 within 10 s"
}

# p95_check <tag> <from-host> <to-host>: 20 sends; fails unless P95 of (API-visible ms + 2000 ms UI poll) <= 5000.
p95_check() {
  pc_file=$(mktemp)
  pc_n=1
  while [ "$pc_n" -le 20 ]; do
    latency_ms "$2" "$3" "lat-$1-$pc_n-$RUN" "lat$1-$pc_n-$RUN" >>"$pc_file"
    pc_n=$((pc_n + 1))
  done
  # P95 of 20 samples is the 19th smallest.
  pc_p95=$(sort -n "$pc_file" | sed -n 19p)
  rm -f "$pc_file"
  pc_total=$((pc_p95 + 2000))
  echo "e2e-latency $1: P95 ${pc_p95} ms API-visible, ${pc_total} ms with the 2 s UI poll"
  [ "$pc_total" -le 5000 ] || fail "e2e-latency $1 P95 ${pc_total} ms > 5000 ms"
}

# ydk:test:system/round-trip.e2e case=e2e-latency
# ydk:nfr:system/e2e-latency
# given: Both Ready
# when: 20 sends each direction, measure API-visible time + 2 s
# then: P95 <= 5 s
case_e2e_latency() {
  p95_check ab "$HOST_CLOPY_PASTE_A" "$HOST_CLOPY_PASTE_B"
  p95_check ba "$HOST_CLOPY_PASTE_B" "$HOST_CLOPY_PASTE_A"
}

# ydk:nfr:system/memory
# given: limits and lru-eviction cases done (B store holds 100 users)
# then: both pods restartCount 0 and never OOMKilled
case_pod_health() {
  for ph_r in clopy-paste-a clopy-paste-b; do
    ph_p=$(pod_of "$ph_r")
    [ -n "$ph_p" ] || fail "no pod for $ph_r"
    [ "$(restarts "$ph_p")" = 0 ] || fail "$ph_p restarted"
    ph_reason=$(kc get pod "$ph_p" -o jsonpath='{.status.containerStatuses[0].lastState.terminated.reason}')
    [ "$ph_reason" != OOMKilled ] || fail "$ph_p was OOMKilled"
  done
}

# ydk:req:ops/network-restricted-exposure
# given: NetworkPolicy admits only the ingress-nginx namespace
# when: curl the A Service port from a pod in a fresh unlabeled namespace; GET A through the Ingress
# then: the in-cluster curl times out (exit 28); the Ingress returns 200
case_network_policy() {
  np_ns="np-probe-$RUN"
  kubectl create namespace "$np_ns" >/dev/null
  trap 'kubectl delete namespace "$np_ns" --wait=false >/dev/null 2>&1 || true' EXIT
  # The default ServiceAccount of a new namespace appears asynchronously; retry the create.
  poll_until 30 kubectl -n "$np_ns" run probe --image="$CURL_IMAGE" --restart=Never --command -- \
    curl -sS -m 5 -o /dev/null "http://clopy-paste-a.$NAMESPACE.svc:8080/readyz" >/dev/null 2>&1 ||
    fail "probe pod not created"
  np_i=0
  while :; do
    np_phase=$(kubectl -n "$np_ns" get pod probe -o jsonpath='{.status.phase}')
    case "$np_phase" in Succeeded | Failed) break ;; esac
    np_i=$((np_i + 1))
    [ "$np_i" -lt 180 ] || fail "probe pod did not finish within 180 s (phase $np_phase)"
    sleep 1
  done
  np_code=$(kubectl -n "$np_ns" get pod probe -o jsonpath='{.status.containerStatuses[0].state.terminated.exitCode}')
  [ "$np_code" = 28 ] || fail "Service port from an unlabeled namespace: want curl timeout (28), got exit $np_code"
  [ "$(http_status "$HOST_CLOPY_PASTE_A" GET /readyz)" = 200 ] || fail "Ingress to A not 200"
}

# broker_gone: succeeds once the broker pod no longer exists.
broker_gone() {
  ! kc get pod "$BROKER_POD" >/dev/null 2>&1
}

# post_is <status> <host> <user>: succeeds when a POST returns the status.
post_is() {
  [ "$(http_status "$2" POST /api/messages "{\"user\":\"$3\",\"text\":\"kd$RUN\"}")" = "$1" ]
}

# kafka_up: restart the Strimzi cluster operator, which recreates the broker pod, and wait until it is Ready.
kafka_up() {
  kc scale deployment/strimzi-cluster-operator --replicas=1 >/dev/null
  poll_until 300 kc get pod "$BROKER_POD" >/dev/null 2>&1 || fail "broker pod not recreated within 300 s"
  kc wait "pod/$BROKER_POD" --for=condition=Ready --timeout=300s >/dev/null || fail "broker not Ready"
  kc wait "kafka/$KAFKA_CLUSTER" --for=condition=Ready --timeout=600s >/dev/null || fail "Kafka not Ready"
  # Ephemeral storage: the new broker has no topics or SCRAM users. Touch the CRs so the entity
  # operator recreates them now instead of at its next periodic reconcile.
  kc annotate kafkatopic,kafkauser --all "e2e-resync=$RUN" --overwrite >/dev/null
}

# ydk:test:system/round-trip.e2e case=kafka-down
# ydk:error:api/kafka-unavailable; readiness independent of Kafka (ADR-016)
# given: Kafka broker pod down. Strimzi rejects KafkaNodePool replicas 0 (no node left), so the cluster
#   operator is scaled to 0 and the broker pod deleted; nothing recreates it until the operator returns.
# when: POST on A through its Ingress; GET page and readiness on A
# then: POST 503 with JSON body {error:'kafka unavailable, message not sent'}; page 200; readiness 200; pod stays Ready, restartCount unchanged; after broker returns, POST 202
case_kafka_down() {
  kd_pod=$(pod_of clopy-paste-a)
  [ -n "$kd_pod" ] || fail "no pod for clopy-paste-a"
  kd_restarts=$(restarts "$kd_pod")
  # Bring the broker back even when an assertion fails, so restart-resume still has Kafka.
  trap 'kafka_up' EXIT
  kc scale deployment/strimzi-cluster-operator --replicas=0 >/dev/null
  kc wait pod -l name=strimzi-cluster-operator --for=delete --timeout=120s >/dev/null 2>&1 || true
  kc delete pod "$BROKER_POD" --wait=false >/dev/null
  poll_until 300 broker_gone || fail "broker pod still present after 300 s"
  poll_until 120 post_is 503 "$HOST_CLOPY_PASTE_A" "kd-$RUN" || fail "POST on A never returned 503 with Kafka down"
  post_check "$HOST_CLOPY_PASTE_A" "{\"user\":\"kd-$RUN\",\"text\":\"down$RUN\"}" 503 'kafka unavailable, message not sent'
  [ "$(http_status "$HOST_CLOPY_PASTE_A" GET /)" = 200 ] || fail "page not 200 with Kafka down"
  [ "$(http_status "$HOST_CLOPY_PASTE_A" GET /readyz)" = 200 ] || fail "readiness not 200 with Kafka down"
  [ "$(kc get pod "$kd_pod" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" = True ] ||
    fail "$kd_pod not Ready with Kafka down"
  [ "$(restarts "$kd_pod")" = "$kd_restarts" ] || fail "$kd_pod restarted with Kafka down"
  trap - EXIT
  kafka_up
  # Ephemeral storage: topics and SCRAM users come back via the entity operator, so allow minutes.
  poll_until 300 post_is 202 "$HOST_CLOPY_PASTE_A" "kd-$RUN" || fail "POST on A not 202 after the broker returned"
  [ "$(restarts "$kd_pod")" = "$kd_restarts" ] || fail "$kd_pod restarted after Kafka returned"
  # Both consumer groups rejoin before restart-resume asserts delivery.
  warm_up "$HOST_CLOPY_PASTE_A" "$HOST_CLOPY_PASTE_B" kdab
  warm_up "$HOST_CLOPY_PASTE_B" "$HOST_CLOPY_PASTE_A" kdba
}

# ydk:test:system/round-trip.e2e case=restart-resume
# ydk:nfr:system/availability, ydk:nfr:system/startup-time and ydk:nfr:system/shutdown-time
# given: B pod deleted
# when: POST on A while B is down; wait for B Ready
# then: deleted pod exits 0 (no SIGKILL); B Ready <= 10 s after container start; message displayed on B
case_restart_resume() {
  rr_old=$(pod_of clopy-paste-b)
  [ -n "$rr_old" ] || fail "no pod for clopy-paste-b"
  rr_watch=$(mktemp)
  kc get pod "$rr_old" -w -o jsonpath='{.status.containerStatuses[0].state.terminated.exitCode}{"\n"}' >"$rr_watch" 2>/dev/null &
  rr_wpid=$!
  trap 'kill "$rr_wpid" 2>/dev/null || true; rm -f "$rr_watch"' EXIT
  sleep 1
  kc delete pod "$rr_old" --wait=false >/dev/null
  # Grace period is 15 s; the process must exit by itself well before SIGKILL.
  poll_until 20 grep -q '[0-9]' "$rr_watch" || fail "$rr_old did not report an exit code within 20 s"
  rr_code=$(grep '[0-9]' "$rr_watch" | head -n 1)
  [ "$rr_code" = 0 ] || fail "$rr_old exited $rr_code (137 = SIGKILL after the grace period)"
  send "$HOST_CLOPY_PASTE_A" "rr-$RUN" "resume$RUN"
  rr_new=
  rr_i=0
  while :; do
    rr_new=$(pod_of clopy-paste-b)
    [ -n "$rr_new" ] && [ "$rr_new" != "$rr_old" ] && break
    rr_i=$((rr_i + 1))
    [ "$rr_i" -lt 60 ] || fail "no replacement B pod within 60 s"
    sleep 1
  done
  kc wait "pod/$rr_new" --for=condition=Ready --timeout=120s >/dev/null || fail "$rr_new not Ready"
  rr_started=$(kc get pod "$rr_new" -o jsonpath='{.status.containerStatuses[0].state.running.startedAt}')
  rr_ready=$(kc get pod "$rr_new" -o jsonpath='{.status.conditions[?(@.type=="Ready")].lastTransitionTime}')
  rr_secs=$(($(date -d "$rr_ready" +%s) - $(date -d "$rr_started" +%s)))
  echo "restart-resume: $rr_new Ready ${rr_secs} s after container start"
  [ "$rr_secs" -le 10 ] || fail "$rr_new Ready ${rr_secs} s after start (> 10 s)"
  wait_ready "$HOST_CLOPY_PASTE_B"
  poll_until 30 has_text "$HOST_CLOPY_PASTE_B" "rr-$RUN" "resume$RUN" || fail "message sent while B was down not shown on B"
}

failed=0
# Destructive cases (kafka-down, restart-resume) run last: they change shared cluster state.
for c in case_a_to_b case_b_to_a case_censoring case_limits case_plain_text case_lru_eviction case_pod_health \
  case_network_policy case_e2e_latency case_kafka_down case_restart_resume; do
  # set -e must stay active inside each case, so the subshell is not an if/&&/|| operand.
  set +e
  ( set -e; "$c" )
  rc=$?
  set -e
  if [ "$rc" -eq 0 ]; then
    echo "ok: $c"
  else
    echo "FAIL: $c"
    failed=1
  fi
done
exit "$failed"
